using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.TKT.EstadosTickets;using GraphApi.Services.TKT.EstadosTickets;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.TKT.EstadosTickets{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de EstadosTickets: creación, actualización y eliminación.")]    public class EstadosTicketsMutation    {        [Authorize]        [GraphQLName("createEstadosTickets")]        [GraphQLDescription("Crea un nuevo EstadosTicket usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadEstadosTickets> CreateEstadosTicketsAsync(            [GraphQLDescription("Datos necesarios para crear el EstadosTicket.")]            clCreateEstadosTickets objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de EstadosTicket.")]            IEstadosTicketsService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateEstadosTickets(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateEstadosTickets")]        [GraphQLDescription("Actualiza los campos especificados de un EstadosTicket existente.")]        public async Task<clReadEstadosTickets?> UpdateEstadosTicketsAsync(            [GraphQLDescription("Datos del EstadosTicket a actualizar.")]            clUpdateEstadosTickets objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de EstadosTicket.")]            IEstadosTicketsService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateEstadosTickets(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteEstadosTickets")]        [GraphQLDescription("Elimina un EstadosTicket por su ID.")]        public async Task<bool> delEstadosTicketsAsync(            [GraphQLDescription("ID del EstadosTicket a eliminar.")]            int nEstadosTicketsID,            [Service]            [GraphQLDescription("Servicio para operaciones de EstadosTicket.")]            IEstadosTicketsService objService        )        {            return await objService.DeleteEstadosTickets(nEstadosTicketsID);        }    }}